script:
test("a visit on the end date is covered and leaves 1", function () {
  assert.deepEqual(code.checkAuthorization({
    approvedVisits: 6,
    usedVisits: 4,
    startDate: "2026-02-01",
    endDate: "2026-04-30",
    visitDate: "2026-04-30"
  }), { covered: true, remaining: 1 });
});

test("a visit one day after the end date is not covered and leaves 2", function () {
  assert.deepEqual(code.checkAuthorization({
    approvedVisits: 6,
    usedVisits: 4,
    startDate: "2026-02-01",
    endDate: "2026-04-30",
    visitDate: "2026-05-01"
  }), { covered: false, remaining: 2 });
});

test("a visit on the start date is covered and leaves 1", function () {
  assert.deepEqual(code.checkAuthorization({
    approvedVisits: 6,
    usedVisits: 4,
    startDate: "2026-02-01",
    endDate: "2026-04-30",
    visitDate: "2026-02-01"
  }), { covered: true, remaining: 1 });
});

test("a visit one day before the start date is not covered and leaves 2", function () {
  assert.deepEqual(code.checkAuthorization({
    approvedVisits: 6,
    usedVisits: 4,
    startDate: "2026-02-01",
    endDate: "2026-04-30",
    visitDate: "2026-01-31"
  }), { covered: false, remaining: 2 });
});

test("a visit one day after the start date is covered and leaves 1", function () {
  assert.deepEqual(code.checkAuthorization({
    approvedVisits: 6,
    usedVisits: 4,
    startDate: "2026-02-01",
    endDate: "2026-04-30",
    visitDate: "2026-02-02"
  }), { covered: true, remaining: 1 });
});

test("a visit one day before the end date is covered and leaves 1", function () {
  assert.deepEqual(code.checkAuthorization({
    approvedVisits: 6,
    usedVisits: 4,
    startDate: "2026-02-01",
    endDate: "2026-04-30",
    visitDate: "2026-04-29"
  }), { covered: true, remaining: 1 });
});

test("a visit when used equals approved is not covered and leaves 0", function () {
  assert.deepEqual(code.checkAuthorization({
    approvedVisits: 6,
    usedVisits: 6,
    startDate: "2026-02-01",
    endDate: "2026-04-30",
    visitDate: "2026-03-15"
  }), { covered: false, remaining: 0 });
});

test("a visit when used is one below approved is covered and leaves 0", function () {
  assert.deepEqual(code.checkAuthorization({
    approvedVisits: 6,
    usedVisits: 5,
    startDate: "2026-02-01",
    endDate: "2026-04-30",
    visitDate: "2026-03-15"
  }), { covered: true, remaining: 0 });
});

test("one approved visit with none used on the start date is covered and leaves 0", function () {
  assert.deepEqual(code.checkAuthorization({
    approvedVisits: 1,
    usedVisits: 0,
    startDate: "2026-03-01",
    endDate: "2026-03-31",
    visitDate: "2026-03-01"
  }), { covered: true, remaining: 0 });
});

test("zero approved and zero used inside the window is not covered and leaves 0", function () {
  assert.deepEqual(code.checkAuthorization({
    approvedVisits: 0,
    usedVisits: 0,
    startDate: "2026-03-01",
    endDate: "2026-03-31",
    visitDate: "2026-03-15"
  }), { covered: false, remaining: 0 });
});

test("last day of December inside a range ending in January is covered and leaves 2", function () {
  assert.deepEqual(code.checkAuthorization({
    approvedVisits: 4,
    usedVisits: 1,
    startDate: "2025-12-01",
    endDate: "2026-01-31",
    visitDate: "2025-12-31"
  }), { covered: true, remaining: 2 });
});

test("first of January inside a range that started in December is covered and leaves 2", function () {
  assert.deepEqual(code.checkAuthorization({
    approvedVisits: 4,
    usedVisits: 1,
    startDate: "2025-12-01",
    endDate: "2026-01-31",
    visitDate: "2026-01-01"
  }), { covered: true, remaining: 2 });
});

test("last day of January as the inclusive end date is covered and leaves 2", function () {
  assert.deepEqual(code.checkAuthorization({
    approvedVisits: 4,
    usedVisits: 1,
    startDate: "2026-01-01",
    endDate: "2026-01-31",
    visitDate: "2026-01-31"
  }), { covered: true, remaining: 2 });
});

test("first of February one day after a January end is not covered and leaves 3", function () {
  assert.deepEqual(code.checkAuthorization({
    approvedVisits: 4,
    usedVisits: 1,
    startDate: "2026-01-01",
    endDate: "2026-01-31",
    visitDate: "2026-02-01"
  }), { covered: false, remaining: 3 });
});

test("leap day as the single covered day is covered and leaves 1", function () {
  assert.deepEqual(code.checkAuthorization({
    approvedVisits: 2,
    usedVisits: 0,
    startDate: "2024-02-29",
    endDate: "2024-02-29",
    visitDate: "2024-02-29"
  }), { covered: true, remaining: 1 });
});

test("an unknown field throws unknown field patientId", function () {
  assert.throws(function () {
    code.checkAuthorization({
      approvedVisits: 6,
      usedVisits: 4,
      startDate: "2026-02-01",
      endDate: "2026-04-30",
      visitDate: "2026-03-15",
      patientId: 1
    });
  }, /^unknown field: patientId$/);
});
